package akogen.fabric.v6;
import java.nio.file.*;import java.util.*;import com.google.gson.*;
public class MultiplayerPerformanceChecks{
 public static class Box{double minX,maxX;public Box(double a,double b,double c,double d,double e,double f){minX=a;maxX=d;}}
 public static class Frustum{public boolean method_23093(Box b){return b.minX<5&&b.maxX> -5;}}
 static boolean mSpecial(Models.Model m){return m.aura||m.wings;}
 static String vertex(float[] f,int k){StringBuilder s=new StringBuilder();for(int j=0;j<8;j++)s.append(Float.floatToIntBits(f[k+j])).append(',');return s.toString();}
 public static void main(String[]args)throws Exception{Assets.load(Files.readAllBytes(Paths.get(args[0])));Names.loader=MultiplayerPerformanceChecks.class.getClassLoader();Names.names=new JsonParser().parse(new String(Files.readAllBytes(Paths.get(args[1])),"UTF-8")).getAsJsonObject();Map<String,Assets.Entry> entries=new LinkedHashMap<String,Assets.Entry>();int original=0,near=0,mid=0,far=0,bones=0;for(Assets.Entry e:Assets.entries){e.model=Models.load(e);e.texture=e.layer=new Object();entries.put(e.name,e);if(e.slot.equals("cloak"))continue;for(Models.Bone b:e.model.bones){original+=b.faces.size();near+=MeshLods.faces(b,2).size();mid+=MeshLods.faces(b,15).size();far+=MeshLods.faces(b,35).size();if(b.lods!=null){bones++;Set<String> authored=new HashSet<String>();for(float[] f:b.faces)for(int k=0;k<32;k+=8)authored.add(vertex(f,k));double[] min={Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY},max={Double.NEGATIVE_INFINITY,Double.NEGATIVE_INFINITY,Double.NEGATIVE_INFINITY};for(float[] f:b.faces)for(int k=0;k<32;k+=8)for(int j=0;j<3;j++){min[j]=Math.min(min[j],f[k+j]);max[j]=Math.max(max[j],f[k+j]);}for(List<float[]> faces:b.lods){for(float[] f:faces)for(int k=0;k<32;k+=8)for(int j=0;j<3;j++)if(f[k+j]<min[j]-.001||f[k+j]>max[j]+.001)throw new AssertionError("LOD scale/bounds mismatch: "+e.name+"/"+b.name);if(faces.isEmpty()||faces.size()>b.faces.size())throw new AssertionError("Bad LOD count");for(float[] f:faces)for(int k=0;k<32;k+=8)if(!mSpecial(e.model)&&!authored.contains(vertex(f,k)))throw new AssertionError("LOD changed fitted vertex/UV/normal on "+e.name+"/"+b.name);}}}}if(!(near<original*.85&&mid<near&&far<mid))throw new AssertionError("Insufficient LOD reduction");SyncChecks.Player a=new SyncChecks.Player(1,0),b=new SyncChecks.Player(2,12);Session.mc=new SyncChecks.MC(a);SyncChecks.Sink sink=new SyncChecks.Sink();World.sink=sink;World.buffers=new SyncChecks.Buffer();Models.Mat view=new Models.Mat();World.drawOwner(a,null,entries,view,0,64,0,1,false,0);if(sink.count<1)throw new AssertionError("Local F5 missing");int local=sink.count;sink.reset();World.drawOwner(b,null,entries,view,0,64,0,1,false,0);if(sink.count<1||sink.count>=local)throw new AssertionError("Remote distance LOD missing");if(!World.visible(a,entries,1))throw new AssertionError("Null frustum should draw");Names.names.getAsJsonObject("classes").addProperty("net/minecraft/world/phys/AABB",Box.class.getName());World.frustum=new Frustum();SyncChecks.Player hidden=new SyncChecks.Player(50,100);if(World.visible(hidden,Collections.<String,Assets.Entry>emptyMap(),1))throw new AssertionError("Offscreen owner not culled");Assets.Entry pet=new Assets.Entry();pet.slot="companion";pet.placed=true;pet.px=0;pet.py=64;Map<String,Assets.Entry> follower=new HashMap<String,Assets.Entry>();follower.put("companion",pet);if(!World.visible(hidden,follower,1))throw new AssertionError("Visible lagging follower incorrectly culled with owner");World.frustum=null;System.out.println("PASS fitted LOD bounds on "+bones+" bones; authored vertices/UVs/normals retained on non-Geass LODs; frustum and visible follower checks PASS; all-cosmetic faces original="+original+" near="+near+" mid="+mid+" far="+far+"; local F5 and remote geometry emitted, vanilla fallback retained");}
}
